{"file_path":"src/address.js","content":"/**
 * Cell-address helpers: parsing an address word into a (column, row) pair,
 * and converting a column number back into its letters for printing.
 *
 * Columns run A..Z (1..26) then AA..ZZ (27..702); rows are 1..999 (at most
 * three digits, and at least 1). A word that does not fit that shape is
 * "outside the addressable range" rather than a parse failure: callers get
 * back `{ valid: false }` and decide what that means for them (usually
 * `#REF!`, or simply "not a dependency").
 */

/**
 * @param {string} raw a word, as written in the sheet or a formula
 * @returns {{ valid: true, col: number, row: number } | { valid: false }}
 */
export function parseAddress(raw) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(raw)
  if (!m) return { valid: false }
  const letters = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return { valid: false }
  const col = letters.length === 1
    ? letters.charCodeAt(0) - 64
    : 26 + (letters.charCodeAt(0) - 64 - 1) * 26 + (letters.charCodeAt(1) - 64)
  return { valid: true, col, row }
}

/** @param {number} col a 1-based column number in 1..702 */
export function columnLetters(col) {
  if (col <= 26) return String.fromCharCode(64 + col)
  const rest = col - 26
  const c1 = Math.floor((rest - 1) / 26) + 1
  const c2 = ((rest - 1) % 26) + 1
  return String.fromCharCode(64 + c1) + String.fromCharCode(64 + c2)
}

/** The canonical printed form of a cell, e.g. `A1`. */
export function addressString(col, row) {
  return columnLetters(col) + row
}

/** A single integer key for a (col, row) pair, suitable as a Map key. */
export function cellKey(col, row) {
  return col * 1000 + row
}
"}

