{"file_path":"src/formula.js","content":"/**
 * Tokenizer and recursive-descent parser for a formula body (the text after
 * the leading `=`). Produces an AST of the node shapes documented below, or
 * throws `ParseError` for anything the grammar does not accept.
 *
 * Node shapes:
 *   { type: 'number', value }
 *   { type: 'bool', value }
 *   { type: 'address', raw }            -- a bare word read as a cell address
 *   { type: 'unary', op, expr }
 *   { type: 'binop', op, left, right }
 *   { type: 'call', name, args }        -- args are expr nodes or range nodes
 *   { type: 'range', from, to }         -- only valid as a direct call argument
 *
 * Precedence, loosest to tightest: comparisons, `+ -`, `* /`, `^`, leading
 * sign. The comparison, additive and multiplicative levels are left
 * associative; `^` is right associative; a leading sign binds to the
 * immediate base only, tighter than `^`, so `-2^2` is `(-2)^2` and `2^3^2`
 * is `2^(3^2)`.
 */

export class ParseError extends Error {}

const COMPARISON_OPS = ['<=', '>=', '<>', '=', '<', '>']

function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const c = text[i]
    if (c === ' ' || c === '\t') { i++; continue }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(text[j])) j++
      tokens.push({ type: 'WORD', value: text.slice(i, j) })
      i = j
      continue
    }
    if (/[0-9]/.test(c)) {
      let j = i + 1
      while (j < n && /[0-9]/.test(text[j])) j++
      if (text[j] === '.' && /[0-9]/.test(text[j + 1] || '')) {
        j++
        while (j < n && /[0-9]/.test(text[j])) j++
      }
      tokens.push({ type: 'NUMBER', value: parseFloat(text.slice(i, j)) })
      i = j
      continue
    }
    if (c === '(') { tokens.push({ type: 'LPAREN' }); i++; continue }
    if (c === ')') { tokens.push({ type: 'RPAREN' }); i++; continue }
    if (c === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (c === ':') { tokens.push({ type: 'COLON' }); i++; continue }
    if (c === '<') {
      if (text[i + 1] === '=') { tokens.push({ type: 'OP', value: '<=' }); i += 2; continue }
      if (text[i + 1] === '>') { tokens.push({ type: 'OP', value: '<>' }); i += 2; continue }
      tokens.push({ type: 'OP', value: '<' }); i++; continue
    }
    if (c === '>') {
      if (text[i + 1] === '=') { tokens.push({ type: 'OP', value: '>=' }); i += 2; continue }
      tokens.push({ type: 'OP', value: '>' }); i++; continue
    }
    if ('^*/+-='.includes(c)) { tokens.push({ type: 'OP', value: c }); i++; continue }
    throw new ParseError(`unexpected character ${c}`)
  }
  tokens.push({ type: 'EOF' })
  return tokens
}

/**
 * @param {string} body the formula text after the leading `=`
 * @returns {object} the parsed AST
 * @throws {ParseError} when the grammar does not accept the text
 */
export function parseFormula(body) {
  const tokens = tokenize(body)
  let pos = 0
  const peek = () => tokens[pos]
  const next = () => tokens[pos++]
  const expect = (type) => {
    const t = next()
    if (t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  function parseComparison() {
    let left = parseAdditive()
    while (peek().type === 'OP' && COMPARISON_OPS.includes(peek().value)) {
      const op = next().value
      const right = parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    while (peek().type === 'OP' && (peek().value === '+' || peek().value === '-')) {
      const op = next().value
      const right = parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    while (peek().type === 'OP' && (peek().value === '*' || peek().value === '/')) {
      const op = next().value
      const right = parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  function parsePower() {
    const base = parseSigned()
    if (peek().type === 'OP' && peek().value === '^') {
      next()
      const right = parsePower()
      return { type: 'binop', op: '^', left: base, right }
    }
    return base
  }

  function parseSigned() {
    if (peek().type === 'OP' && (peek().value === '-' || peek().value === '+')) {
      const op = next().value
      const expr = parsePrimary()
      return { type: 'unary', op, expr }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()
    if (t.type === 'NUMBER') { next(); return { type: 'number', value: t.value } }
    if (t.type === 'LPAREN') {
      next()
      const e = parseComparison()
      expect('RPAREN')
      return e
    }
    if (t.type === 'WORD') {
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') { next(); return { type: 'bool', value: true } }
      if (upper === 'FALSE') { next(); return { type: 'bool', value: false } }
      if (tokens[pos + 1] && tokens[pos + 1].type === 'LPAREN') {
        next() // WORD
        next() // LPAREN
        const args = []
        if (peek().type !== 'RPAREN') {
          args.push(parseArg())
          while (peek().type === 'COMMA') { next(); args.push(parseArg()) }
        }
        expect('RPAREN')
        return { type: 'call', name: upper, args }
      }
      next()
      return { type: 'address', raw: t.value }
    }
    throw new ParseError('unexpected token')
  }

  function parseArg() {
    if (peek().type === 'WORD' && tokens[pos + 1] && tokens[pos + 1].type === 'COLON') {
      const from = next().value
      next() // COLON
      const t2 = peek()
      if (t2.type !== 'WORD') throw new ParseError('expected address after :')
      const to = next().value
      return { type: 'range', from, to }
    }
    return parseComparison()
  }

  const result = parseComparison()
  if (peek().type !== 'EOF') throw new ParseError('trailing tokens')
  return result
}
