{"file_path":"src/values.js","content":"/**
 * The value model: every cell holds a number, text, a boolean, or an error
 * (one of the six error tokens). Values are tagged plain objects so callers
 * can branch on `.t`.
 */

export const numV = (v) => ({ t: 'num', v })
export const textV = (v) => ({ t: 'text', v })
export const boolV = (v) => ({ t: 'bool', v })
export const errV = (v) => ({ t: 'err', v })

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

/** Parses a literal cell (content that is not a formula). */
export function parseLiteral(content) {
  if (content === '') return numV(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return numV(parseFloat(content))
  if (ERROR_TOKENS.has(content)) return errV(content)
  return textV(content)
}

/** Reads a value in an arithmetic position; text yields `#VALUE!`. */
export function toNumber(val) {
  if (val.t === 'err') return { ok: false, err: val }
  if (val.t === 'num') return { ok: true, n: val.v }
  if (val.t === 'bool') return { ok: true, n: val.v ? 1 : 0 }
  return { ok: false, err: errV('#VALUE!') }
}

/** Reads a value as an IF condition: TRUE/nonzero is true, FALSE/zero is false. */
export function toCondition(val) {
  if (val.t === 'err') return { ok: false, err: val }
  if (val.t === 'bool') return { ok: true, b: val.v }
  if (val.t === 'num') return { ok: true, b: val.v !== 0 }
  return { ok: false, err: errV('#VALUE!') }
}

// Numbers order below text, which orders below booleans; within a kind,
// numbers compare numerically, text by code point, and false below true.
const typeRank = (val) => (val.t === 'num' ? 0 : val.t === 'text' ? 1 : 2)

export function compareValues(a, b) {
  const ra = typeRank(a)
  const rb = typeRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num' || a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const av = a.v ? 1 : 0
  const bv = b.v ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

/** Rounds to ten significant digits, then formats as JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

/** Formats a value for `values` output. */
export function formatValue(val) {
  if (val.t === 'err') return val.v
  if (val.t === 'bool') return val.v ? 'TRUE' : 'FALSE'
  if (val.t === 'text') return val.v
  return formatNumber(val.v)
}
"}

