{"file_path":"src/sheet.js","content":"/**
 * Parses the raw sheet text into a map of declared cells, applying the
 * line-splitting, comment, and address rules from the spec. Throws
 * `SheetError` for the two failure cases the CLI reports.
 */

import { parseAddress, cellKey } from './address.js'
import { parseLiteral } from './values.js'
import { parseFormula, ParseError } from './formula.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/**
 * @param {string} text the raw stdin content
 * @returns {Map<number, object>} cell records keyed by `cellKey(col, row)`,
 *   each `{ col, row, kind: 'literal', value } | { col, row, kind: 'formula', ast, state }`
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const sheet = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^([ \t]*)/.exec(stripped)
    const wsIdx = /[ \t]/.exec(stripped)
    let addressRaw, content
    if (wsIdx === null) {
      addressRaw = stripped
      content = ''
    } else {
      addressRaw = stripped.slice(0, wsIdx.index)
      const rest = stripped.slice(wsIdx.index)
      const skip = /^[ \t]+/.exec(rest)
      content = rest.slice(skip[0].length)
    }

    const addr = parseAddress(addressRaw)
    if (!addr.valid) {
      throw new SheetError(`invalid cell address ${addressRaw}`)
    }
    const key = cellKey(addr.col, addr.row)
    if (sheet.has(key)) {
      const canonical = require_addressString(addr.col, addr.row)
      throw new SheetError(`cell ${canonical} is declared twice`)
    }

    const record = { col: addr.col, row: addr.row }
    if (content.startsWith('=')) {
      try {
        record.kind = 'formula'
        record.ast = parseFormula(content.slice(1))
        record.state = 'unvisited'
      } catch (e) {
        if (!(e instanceof ParseError)) throw e
        record.ast = null
      }
    } else {
      record.kind = 'literal'
      record.value = parseLiteral(content)
    }
    sheet.set(key, record)
  }
  return sheet
}

// Small local helper to avoid a circular import concern; kept private here.
function require_addressString(col, row) {
  const letters = col <= 26
    ? String.fromCharCode(64 + col)
    : (() => {
        const rest = col - 26
        const c1 = Math.floor((rest - 1) / 26) + 1
        const c2 = ((rest - 1) % 26) + 1
        return String.fromCharCode(64 + c1) + String.fromCharCode(64 + c2)
      })()
  return letters + row
}
"}

